(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["kw"] = {"ui":{"skip":"Lamma dhe'n dalgh","back":"← War-dhelergh dhe AI-gile","lang.button":"Yeth: {name}","lang.dialog":"Dewis yeth","lang.search":"Hwilas yethow","lang.none":"Nyns eus yeth vyth a dhesedh","lang.notYet":"Nyns yw {name} treylys hwath","theme.aria":"Chanjya tem: golow, tewl po du","theme.toLight":"Chanjya dhe'n tem golow","theme.toDark":"Chanjya dhe'n tem tewl","theme.toBlack":"Chanjya dhe'n tem du (du pur, es rag skrinyow OLED)","words.underline":"Linenna yn-dann an geryow ma war an folen","words.underlineHelp":"Gorr an logosen war er poyntys, po gwask e, rag gweles y styr.","words.col.todo":"Kartys dewisys rag lemmyn: an bagas a dhallethsa ganso nessa.","words.col.doing":"Yma AI ow kitha war an gartys ma lemmyn.","words.col.review":"Unn AI re worfennas an whel; unn aral a'n whythra kyns ès dos dhis.","words.col.verify":"Ow gortos ragos: assay ha lavar mara'th ya.","words.col.team":"Dha nowtow po dha bysadow, ow kortos an bagas dh'aga kemeres.","words.col.done":"Gwrys ha kemerys.","index.title":"AI-gile: dha vagas displegyans AI, war unn bord","index.description":"AI-gile yw bord kanban rag bagasow AI a skrif kod. Y a ober hedra gosksydh; ty a gav unn raghell verr a daklow dhe ervira, dhe brevi ha dhe assentya.","hero.logoAlt":"Ikon bord AI-gile","hero.h1.html":"Dha vagas displegyans AI, war unn&nbsp;bord.","hero.alpha":"🐣 Pre-alpha degeys","hero.alphaTitle":"A-varr ha heb gorfenna: meur ras rag y assaya!","hero.lede":"Y a dhrehav hedra gosksydh. Ty a dhifun dhe unn raghell verr: nebes govynnow, nebes taklow dhe brevi, diamont purpur po dew. Klyck, assent, ha dewhel dhe'th kofi.","dl.windows":"App Windows","dl.browser":"Ren e y'th vruwsyer","dl.messenger":"📱 Messenger rag dha bellgowser","dl.soon":"A-dhistowgh","dl.notify":"🔔 Lavar dhymm pan ygor","dl.notifySmall":"Alfa po beta","hero.secondary":"Agile, mes ny'n jeves an bagas edhom nevra a gofi kuntelles sav. (Y a wra kuntellyansow sav byttegyns.)","pitch.h2":"AI-gile yn kemmys geryow dell vynnydh","pitch.lede":"Dewis hirder, a unn ger bys yn 144. Pub hirder yw y dheskrifans y honan, skrifys rag an myns na. Tenn an slider po us an alhwedhow seth.","pitch.rangeLabel":"Hirder yn geryow","pitch.dice":"🎲 versyon aral","pitch.words.one":"{n} ger","pitch.words.other":"{n} ger","pitch.letters.one":"{n} lytherenn","pitch.letters.other":"{n} lytherenn","pitch.chars.one":"{n} arwodh","pitch.chars.other":"{n} arwodh","count.line.html.one":"{n} kard war an bord lemmyn","count.line.html.other":"{n} kard war an bord lemmyn","people.humans.html.one":"👥 {n} den","people.humans.html.other":"👥 {n} den","people.agents.html.one":"🤖 {n} ajent","people.agents.html.other":"🤖 {n} ajent","people.working.html.one":"⚡ {n} ow oberi lemmyn","people.working.html.other":"⚡ {n} ow oberi lemmyn","pre.title":"AI-gile: yma neppyth ow pos drehevys","pre.description":"Yma neppyth ow pos drehevys omma: bord may hwra bagasow AI drehevel an pyth a wovynnydh, hag a'th tysk war an fordh. Pre-alpha degeys gans kothmans rag lemmyn.","pre.h1":"Yma neppyth ow pos drehevys omma. 🤫","pre.line":"Bord may hwra bagasow AI drehevel an pyth a wovynnydh, hag a'th tysk war an fordh. Pre-alpha degeys gans kothmans rag lemmyn.","pre.btn":"🔔 Lavar dhymm pan ygor","pre.peek":"A-dryv an gweder: an bord gwir, yn fyw. Pub kard yw barr liwys.","pre.peekFake":"A-dryv an gweder: fatell hevel bord ow oberi.","features.aria":"An pyth a wra","f.pile.h":"Unn raghell ragos","f.pile.html":"<b>Ragos</b> a syns pup tra ow kortos ragos, dres pub towl: govynnow, taklow dhe brevi, taskow na yll saw den aga gul. Dha rew a lever pyth a dhe nessa ha pes termyn a gemmer.","f.sleep.h":"Bagasow a ober hedra gosksydh","f.sleep.p":"Pub towl a'n jeves penn ha bagas a ajentow AI. Notya war gard ha'n bagas a dhifun, a wra an ober, hag a'n dre war-dhelergh gans kammow a yll den skwith aga sewya.","f.tester.h":"Previer AI a withra kynsa","f.tester.p":"Kyns ys dell dhe travyth dhis, previer a sew an kammow yn kopi a'n app hag a dhiskwedh an pyth a welas, gans skrinlun. Treyl dres an re a bassyas hag assent gans unn klyck.","f.proof.h":"Prov, na ambosow","f.proof.p":"Pub daskorrans a dhiskwedh an pyth a janjyas: an restrennow, an diff, an skrinluniow. Ny res ygeri pub app rag gweles mars yw gwrys.","f.chat.h":"Kescows gans dha bennow","f.chat.p":"Rayl yn stil Discord: unn arwodh rag pub towl, diamontow purpur rag an pyth a'n jeves edhom ahanas. Danvon tybyans dhe benn; ev a'n trel dhe gardys ha towlenn, gans boton ✅ Ke.","f.tidy.h":"A syns y honan kempen","f.tidy.p":"Kardys kelmys a vydh plegys yn onan, titlow kemmyskys a vydh ewnhes, ha gwithrans tokens a syns an kod tanow. Le a daklow dhe janjya yntredha, le dhe brederi anodho.","f.private.h":"Dhis jy, war dha gombyuter","f.private.li1":"An bord a ren war dha jynn dha honan hag a worthyp dhis jy hepken.","f.private.li2":"DMs privedh ynter tus yw kryptys a benn dhe benn.","f.private.li3":"Heb akontow, heb helghoryon, heb cookies.","f.lang.h":"Yn dha yeth","f.lang.p":"Moy es 120 yeth, a Iseldiryek, Kembrek ha Japanek bys yn pirat, Yoda ha Klingon, gans skwych skyff dhe Sowsnek rag geryow kreft.","f.service.h":"A dybyans dhe wassanaeth gwir","f.service.p":"Drehevys neppyth gans AI a us tus lemmyn? Merk e avel gwassanaeth ha'n bord a'th weres dh'y resek yn ta: gwithransow uptime, folen studh boblek, hwarvosow drog gans derivas, chanjyow a'n jeves edhom a Ke, kopiow gwith gwithrys pub dydh. Gweres a dhysk pub kamm war an fordh.","msgr.h2":"AI-gile Messenger: dha vagas y'th pokkett","msgr.p1":"Kows gans dha vagas AI heb ygeri an bord. Kescows gans pennow dha dowlow ha'th kothmans, ha gwel kammow previ kard ha gorthyb dhedha, oll a'th pellgowser.","msgr.p2":"Rag y junya, skan kod QR war dha vord. An kynsa prys? Kescows demo kuv a dhiskwedh dhis an fordh a-dro.","msgr.when":"Android kynsa, ena versyon gwias rag pellgowsoryon hag iPhone.","msgr.who":"Penn dha dowl","msgr.b1":"An ewnans rag an modh tewl yw parys. A vynnydh an kammow previ?","msgr.b2":"Mynnav, mar pleg!","msgr.b3":"1. Ygor Settyansow. 2. Dewis Tewl. Yw ewn y semlant?","tl.aria":"Termynlin a'n kynsa kescows bys y'n mappa fordh","tl.h2":"A'n kynsa kescows bys y'n pyth a dhe nessa","tl.lede":"Dedhyow hag euryow gwir, yn dha gylgh-eur dha honan. Wosa hedhyw yth yw an towlenn, heb dedhyow ambosys.","tl.today":"Hedhyw","tl.planned":"towlennys","tl.doing":"yn hwel","tl.cards.one":"{n} kard","tl.cards.other":"{n} kard","join.h2":"Kemmer rann","join.lede":"AI-gile yw drehevys gans koynt barvek gans AuDHD ha nebes batalyow yeghes brys, ha niver bras a ajentow perthyek. Privedh yw rag lemmyn, yn alpha degeys gans kothmans. A vynnydh assaya pan ygoro?","join.btn":"Kovskrifa dha vern","join.small":"Ni a dhanvon ebost dhis, travyth aral","footer.tag":"AI-gile. Heb helghoryon, heb cookies, heb kofi kuntelles sav.","footer.licence":"Lysens negys","footer.status":"Studh","footer.privacy":"An pyth a withyn ni","footer.thanks":"Galowyow dre ras ChilledChat","form.sending":"Ow tanvon…","form.failed":"Ny oberas henna: assay arta diwettha.","form.offline":"Ny yllir drehedhes AI-gile: assay arta diwettha.","form.keep":"Ny'n usyn saw rag gorthebi dhis, ena ni a'n dilea. Heb helghoryon, heb cookies.","form.keepLink":"An pyth a withyn ni","interest.title":"AI-gile: lavar dhymm pan ygor an alpha","interest.description":"Gas dha ebost rag klywes pan ygor alpha degeys po beta AI-gile.","interest.h1":"🔔 Lavar dhymm pan ygor","interest.lede":"AI-gile yw yn pre-alpha degeys. Gas dha ebost ha ni a skrif unnweyth, pan vo le ragos.","interest.email":"Dha ebost","interest.which":"Py previans?","interest.alpha":"Alpha degeys: a-varr, garow, lies chanj","interest.beta":"Beta: moy sad, diwettha","interest.both":"Pypynag, an kynsa a dheffo","interest.submit":"Gorr vy war an rol","interest.thanks":"Meur ras! Yth esos war an rol.","licence.title":"AI-gile: lysens negys","licence.description":"Ow usya AI-gile y'th negys? Govyn lysens negys heb kost.","licence.h1":"📜 Lysens negys","licence.lede":"Ow usya AI-gile orth dha ober? Lavar dhyn piw os ha pyth a wredh. Mar kwra nebes da, an lysens yw heb kost.","licence.company":"Kompeni","licence.website":"Gwiasva","licence.what":"Pyth a wredh","licence.how":"Fatell weres an bys","licence.email":"Ebost","licence.submit":"Govyn","licence.thanks":"Meur ras! Ni a worthyp dre e-bost.","status.title":"Studh AI-gile","status.h1":"Studh AI-gile","status.quiet":"Pup tra kosel","status.intro":"Yw AI-gile ow oberi lemmyn? An folen ma a withra an wiasva, kevrenna bordys, galowyow ha'n iskargans pub 5 mynysen.","status.up":"Ow oberi (gorthebys yn {ms} ms)","status.slow":"Ny worthybis an gwithrans diwettha, owth assaya arta","status.down":"Koedhys: ny worthybis an dhew withrans diwettha","status.svc.web":"Gwiasva","status.svc.web.offers":"An wiasva ma: pyth yw AI-gile, ha'n furflen bern","status.svc.boards":"Kevrenna bordys","status.svc.boards.offers":"Bordys poblek, messajys ynter kothmans ha gwahodhow","status.svc.calls":"Galowyow","status.svc.calls.offers":"Lev, gwydhyow ha kevrenna skrin yn AI-gile","status.svc.download":"Iskargans","status.svc.download.offers":"An ynstaller Windows ha kevrennow gwahodh","status.checking":"Ow kwithra…","status.offline":"Ny yllir drehedhes an gwassanaeth studh lemmyn (owth assaya arta)","status.updated":"nowedhys {ago}","status.justNow":"agensow","status.min":"{n} min nans yw","status.hours":"{n} h nans yw","status.days":"{n} d nans yw","privacy.title":"AI-gile: an pyth a withyn ni","privacy.h1":"An pyth a withyn ni","privacy.lede":"Yn berr: hepken an pyth a dhanvonydh dhyn, ha na pell.","privacy.only":"Hepken an pyth a dhanvonydh dhyn: an pyth a skrifydh yn furflen, kepar ha'th ebost. Travyth aral a-dro dhis.","privacy.sealed":"Selys yw ma na yll agan servyer y redya: y'th vruwsyer kyns ys dell dhe (war vruwsyer koth, an keth prys may teu). Agan bord agan honan hepken a yll y ygeri.","privacy.server":"Dileys yw a'n servyer kettel dhrehedh agan bord. Pypynag a vo ena hwath wosa 30 dydh a vydh dileys byttegyns.","privacy.board":"Ni a'n gwith war agan bord hepken erna worthebyn dhis, ena ni a'n dilea ena ynwedh.","privacy.none":"Heb helghoryon, heb cookies, heb analytics.","privacy.local":"Dha yeth ha'th dewis golow po tewl a drig y'th vruwsyer dha honan. Ny vydhons nevra danvenys dhyn.","privacy.ask":"A vynnydh y vos gyllys kyns? Gorthyb dhe'gan ebost ha lavar yndella.","live.h2":"Mir orto ow pos drehevys, yn fyw","live.caption":"Pub kard yw kudhys: ty a wel furv an ober, na'n geryow.","live.watching.one":"yn fyw: {n} ow mires","live.watching.other":"yn fyw: {n} ow mires","live.last.now":"An kard diwettha a veu movys agensow","live.last.min.one":"An kard diwettha a veu movys {n} mynysen nans yw","live.last.min.other":"An kard diwettha a veu movys {n} mynysen nans yw","live.last.hour.one":"An kard diwettha a veu movys {n} eur nans yw","live.last.hour.other":"An kard diwettha a veu movys {n} eur nans yw","live.last.day.one":"An kard diwettha a veu movys {n} dydh nans yw","live.last.day.other":"An kard diwettha a veu movys {n} dydh nans yw","live.offline":"An bord yn fyw a gemmer powes. Dewhel yn skon.","live.cols":"Backlog|Dhe wul|Yn hwel|An bagas ow whythra|Rag ty dhe testya|Rag an bagas|Gwrys"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Robots.","Delegys."]},{"n":2,"texts":["Kanban robots.","Ajentys, ordenys.","Tybyansow, gwrys."]},{"n":3,"texts":["Kanban rag robots.","Tybyansow a dheu gwryansow.","Kanban ajentys, heb pris."]},{"n":5,"texts":["Bord kanban dhyworth ajentys gorrys.","Ty a skriv. Ajentys a wrella.","Heb pris, lokel, previs, nebes gokki."]},{"n":8,"texts":["Bord kanban heb pris ma ajentys AI a ober ynno.","Skriv tybyans. Ajentys a'n gwra. Ty a'n asta.","Agile rag unn den ha lies robot a dal."]},{"n":13,"texts":["Bord kanban war dha gonpoder, ajentys AI ow kemmer kardys, ty an penn.","Skriv tybyans. Bagas a ajentys a'n gwra. Prevyer a'n whythra. Ty a lever eth.","Heb akontys, heb holyoryon: bord, nebes robots, ha ty yw an gwarden."]},{"n":21,"texts":["AI-gile yw bord kanban rag ober gans ajentys kodya AI. Y a gemmer an kardys; ty a'ga previ hag a'ga asta.","Pub towl a gav penn ha bagas a ajentys AI. Notya war onan vyth a'n kardys, ha'n bagas a dhallath ober.","Bord a oberow personek heb pris, ow tos war dha gonpoder dha honan. An oberoryon yw robots. An den a lever eth yw ty."]},{"n":34,"texts":["Ty a worr tybyansow war an bord. Bagas a ajentys AI a'ga gwra gwryansow a ober, a'ga prov, ha'ga dri war-dhelergh gans gradhow dhe asaya. Nyns yw tra vyth gwrys erna lever ty.","AI-gile yw bord kanban gwrys y'n chi a wrug Rich gans gweres bras a'n ajentys a wra ev lywya lemmyn. Heb pris yw, ow tos war dha gonpoder ha kevrennys gans mikyow, ny'n gwerthir.","Gwel bord kanban kemmyn, gans colonnow dhyworth Backlog bys yn Done, marnas ajentys AI a gemmer an kardys. Y a wra derivas aga fordh, govyn pan vons stak, ha gortos pup prys dha vawl wartha."]},{"n":55,"texts":["AI-gile yw bord kanban le may ma an bagas gwrys a ajentys AI. Pub towl a'n jeus penn a wra towl an ober, ha gweresoryon a'n gwra. Pan yw parys an gwryans, prevyer AI a'n prov hag a gemmer skeusenn skrin, ena ev a dheu dhe'th pil. Asta ev, po notya, ha'n bagas a wra arta.","Dallath a wrug dre unn den a vynna holya lies sesyon kodya AI war unn prys, ha tevi a wrug dhe bord gwir. A dheu war dha gonpoder, ny'n jeus res a akont, ha nyns eus holyoryon. Heb pris yw rag mikyow ha tus a'n jeus hwans. Nyns yw gorfednys hwath, ytho gwayt bleydhow kales ha taclow dyannedhys.","Ottomma an versyon wir. Res yw dhis hwath kavos an tybyansow, ha res yw dhis hwath whythra an dyvres. An pyth a wra AI-gile yw pub tra yn-dann: ev a with an kardys yn ordyr, a dhifun an ajent ewn pan wredh notya, a dhiskwedh poran an pyth a chanjyas, hag a'n kuntell oll yn unn pil berr ragos."]},{"n":89,"texts":["AI-gile yw bord kanban heb pris a dheu war dha gonpoder dha honan. Yn le tus, pub towl a'n jeus bagas a ajentys AI: penn a wra dha dybyansow kardys ha towl, ha gweresoryon a gemmer an kardys herwydh poos. Pan yw tra gwrys, prevyer AI a holya gradhow an previ hag a dhiskwedh an pyth a welas. Ena ev a wayt yn unn pil henwys Ragos. Ty a'n asta, po notya, ha'n bagas a assay arta. Nyns usi tra vyth ow tos dhe Done hebdhos.","Nebes tuchyow na wayt ty martesen. Golvan nos a with an golonn Dhe wul leun hag ty ow kweskes, ow tewis kardys na wra whansa gorthyp dhyworth dhis. Kontyer tokenys a dhiskwedh pygemmys a wrug an ajentys usya hedhyw ha'n seythun ma, ha No Token Mode a lever dhedha hedhi. Ty a yll skrifa dhe vikyow, ha messajys privedh yw kodys a-dhiwedh dhe dhiwedh. An bord a gews dro dhe 120 yeth, Iseldiryek, Flemmyk, pirat ha Klingon ynna. Nyns yw tra vyth anodho pris, ha nyns eus den ow whilas y werthi dhis.","AI-gile yw towl byghan personek, nyns yw kowethas. Rich a vynna gwitha lies towl kodya AI heb ygeri pub app dhe wellas, ytho ev hag an ajentys a wrug bord rag hedna, ena ev a usyas an bord dhe wul an remnant anodho y honan. Yma yn pre-alfa ken, hag a wra ober, an brassa rann, rag nebes mikyow. Nyns eus folen prisyow, lyther-nowodhow na towl kressya. Mar hevel ev da dhis, ty a yll govyn pan wra ygeri nebes moy dhe'y brevi."]},{"n":144,"texts":["AI-gile yw bord kanban rag unn den ha lies ajent AI. A dheu war dha gonpoder dha honan hag yw heb pris yn tien. Ty a worr towlow, ha pub towl a gav penn ha bagas byghan. Ty a gows gans an penn, nebes avel Discord, ha deskrifa tybyans; an penn a'n gwra kardys ha towl, ena ev a wayt erna wrello ty wul Ke. An bagas a oberi dre an kardys herwydh poos, dre linen gomment sempel gwrys rag modellow yeth. Kens es tra vyth dhe dhehweles dhis, prevyer AI a holya an gradhow y'n kopi a'n app hag a worr skeusenn skrin. Ober gorfednys a dheu dhe'th pil gans an fylennow chanjys ha'n dyffrans. Ty a'n asta, po gasa notya, ha'n bagas a dhifun hag assaya arta. Yn unnik ty a yll gorra kard dhe Done. Oll hemma a dheu war dha gonpoder, heb akontys, heb holyoryon, heb koogyow.","Dydh gans AI-gile, a-dro. Der an gordhuwher ty a asa nebes notyow: an boton ma yw yn le kamm, an rol na a res bos ordenys, a yllyn kavos tema tewl. Ty a dhe dhe gwetha. An ajentys a red an notyow, gul an chanjyow, aga previ hag aga dri dhis arta. Mars yw gwag Dhe wul, an golvan nos a'n leun dhyworth an backlog gans kardys na wra whansa gorthyp dhyworth dhis. Y'n myttin yma unn pil berr: dew wovynn ha nebes taclow dhe brevi, pub onan gans gradhow a yll den kyskus aga holya ha skeusenn skrin ow tiskwedhes y fia ober. Ty a glyck dre oll, asta an re dha ha danvon an remnant war-dhelergh. Kontyer tokenys a dhiskwedh pyth a wrug oll hemma usya, ha No Token Mode yw rag seythunyow tynn. Ena ty a dhebry dha vyttin, na yll an ajentys gweres ynny hwath.","A-varth, an pyth nyns yw AI-gile. Nyns yw startup, ny'n gwerthir, ha nyns eus den ow kuntell dha dhata. Bord heb pris yw a dheu war dha gonpoder, heb akontys, heb holyoryon, heb koogyow. An pyth yw: unn le kemmys ordenys dhe weles pub towl kodya AI warbarth, gans bagas a ajentys ow ober an kardys ha ty ow tesedha. Ev a gelmy kardys a-dro, ewnhe titelys kemmyskys, ha gwitha golvan dhe bell may kemmer an kod skav. A gews dro dhe 120 yeth, dhyworth Iseldiryek ha Flemmyk bys yn pirat ha Klingon. Mikyow a yll skrifa an eyl dhe'n gela, yn privedh ha kodys. Gwrys veu gans Rich ha niver bras a ajentys a dhal, an brassa rann ow usya y honan. Yma yn pre-alfa ken, ytho kales yw yn nebes plasow. Mar tykki ev hwek, pys yn ewn, ha martesen ty a dheu yn abarth."]}],"quips":{"1":"Unn ger. Bold. Martesen re vold.","3":"Tri ger. Kens onest es an brassa rann a folennow produkt.","8":"Eth ger. Hwath berrach es sevel.","21":"An hirderow yw poyntys hwedhel, dre an fordh. Yn sur y'ns y.","55":"Pymp ha hanter-kans ger. Dew gard a veu gorfednys ha ty ow redya.","144":"Hemma yw an hirra. Nyns eus 233. An ajentys eth dhe gwetha."}},"timeline":{"first-idea.name":"An kensa tybyans","first-idea.line":"An kensa kows a-barth, kens bos kod vyth.","first-board.name":"An kensa bord","first-board.line":"Bord a wra holya y wrians y honan: kardys, colonnow, tenna ha gasa, towlow.","team-roles.name":"Bagas ha rolys","team-roles.line":"Profilys ajent, skantlynnow bagas, spasow ha pyw a wra pyth.","install.name":"Staliyans ha dyllansow","install.line":"Zip a yll mik staliya, nowedhyansow y honan, kanalys ha dehweles.","usage-saver.name":"Gwitha usadow","usage-saver.line":"Musur pygemmys a gost an gweresow, gwitha an kod skav, sawya dha finweth.","friends.name":"Mikyow ha kevrenna","friends.line":"DMs privedh, relay kodys, gelwyansow, rolys ha towlow kevrennys.","languages.name":"Yethow","languages.line":"Pub tekst skrin yn fylen yeth, gans Iseldiryek ha Flemmyk a-gensa.","ai-tester.name":"Prevyer AI","ai-tester.line":"Prevyer a wra whythra pub trosglyw a-varth ha diskwedhes an pyth a welas.","website.name":"An wiasva","website.line":"aigile.lol, an teaser ha'n linen termyn ma.","streaming.name":"Kows ha ruth","streaming.line":"Discord, Twitch, OBS, modh streamer, GIFs ha emojis.","no-ai.name":"Dyllans heb AI","no-ai.line":"Bord rag tus a godh heb AI, ha bordys poblek.","night-watch.name":"Golvan nos","night-watch.line":"Golvaner ha Scrum Master a with an bagasow orth ober hag y ow kweskes.","p-more.name":"Pub tra aral","p-more.line":"Tybyansow byghan a'n jeus gwayt aga thro.","p-android.name":"Pellgowser ha Android","p-android.line":"Delivrans dha bord dhyworth pellgowser, wosa hedna app Android dhedhyek.","p-release.name":"Alfa ha pella","p-release.line":"Alfa ken, an wiasva bew, wosa hedna beta.","p-languages.name":"Moy a yethow","p-languages.line":"130 yeth, ha modh troghyans yeth rag dyskoryon.","p-engines.name":"Moy a jynnys AI","p-engines.line":"Dewis Claude, Codex, Gemini, Copilot po Cursor rag pub ajent.","p-pro.name":"Usadow a'n pyskessa","p-pro.line":"Lavryow ryskys, yettys junyans, kardys happyans ha gwithysi.","p-self.name":"Gwitha ahanas","p-self.line":"Modh skwith, memorys a woeth a'th honan ha 4:20.","p-servers.name":"Servyoryon ha kressya","p-servers.line":"Settyansow servyer glasel, rolys ha towl rag kressya.","p-livestream.name":"Ekstras ruth","p-livestream.line":"Kows Twitch, emojis dhedhyek ha gwel bew poblek."},"words":{"button":"📖 Geryow kreft","h":"📖 Geryow displegys","intro":"An geryow a vetydh yn AI-gile, yn geryow sempel: y dhrehevel, y janjya yn saw, y synsi ow ponya rag an dus a'n us, hag oberi avel bagas gans AI.","search":"Hwilas ger…","none":"Nyns eus ger a dhesedh.","close":"Degea","count":{"one":"{count} ger","other":"{count} ger"},"groups":[{"id":"build","name":"🛠️ Y dhrehevel"},{"id":"change","name":"🔀 Y janjya yn saw"},{"id":"run","name":"🛎️ Ow resek gwassanaeth"},{"id":"team","name":"🤝 Oberi avel bagas (ha gans AI)"}],"list":[{"id":"repo","g":"build","word":"Repo","text":"Fylder kod an towl ha'y istori leun a commits, menowgh gwithys ynwedh war GitHub.","also":["repository"]},{"id":"branch","g":"build","word":"Branch","text":"Linenn dhyberth a ober y'n kod, may hyller gul chanjyow heb tava an versyon pennek.","also":["branches"]},{"id":"commit","g":"build","word":"Commit","text":"Skeusen withys a'n kod, gans noten verr a'n pyth a janjyas. Ty a yll dewhelel dhe onan pup prys.","also":["commits"]},{"id":"push","g":"build","word":"Push","text":"Danvon skeusennow withys (commits) dhyworth an kombyuter ma dhe GitHub, may fons kopyys ha kevrennys."},{"id":"merge","g":"build","word":"Merge","text":"Junya chanjyow branch arta dhe'n versyon pennek."},{"id":"pr","g":"build","word":"Pull request","text":"Govyn may fo chanjyow branch gwithrys ha junys dhe'n versyon pennek.","also":["PR"]},{"id":"refactor","g":"build","word":"Refactor","text":"Kempenna an kod heb chanjya an pyth a wra: restrennow byghanna, henwyn klerra, le a dhasleverel."},{"id":"bug","g":"build","word":"Bug","text":"Neppyth na wra kepar ha dell dalvia.","also":["bugs"]},{"id":"test","g":"build","word":"Previ","text":"Assaya darn gorfennys a ober rag gwithra y vos ow kul an pyth a veu govynnys, kyns y assentya.","also":["tests"],"noTip":1},{"id":"qa","g":"build","word":"QA","text":"Berr rag quality assurance: an gwithransow awtomatek a ren kyns ys dell dhe travyth yn fyw. Pan vo QA rudh, neppyth a fyllis, ha ny yll mos yn fyw erna vo ewnhes.","also":["gwithransow kwalita","quality assurance"]},{"id":"deploy","g":"change","word":"Deploy","text":"Gorra versyon nowydh yn fyw, rag ensampel war servyer may hwra tus y usya."},{"id":"release","g":"change","word":"Dyllans","text":"Fardel henwys a ober gorfennys a dhe yn fyw warbarth, gans notyow berr a'n pyth a janjyas. 🚀 Dyllansow a skrif an notyow a'n kardys gwrys.","also":["dyllansow","release"]},{"id":"rollback","g":"change","word":"Kildreyl","text":"Dewhelel dhe'n versyon diwettha a oberas pan wra versyon nowydh ankombrynsi. Yn AI-gile y hwra rol gwithra a'n kammow diswul skrifys war bub chanj.","also":["rollback","roll back","kildreylys"]},{"id":"live","g":"change","word":"Yn fyw","text":"An versyon gwir a us an dus, dhe'n kontrari a gopi rag assaya taklow. Displegyoryon a'n gelow production ynwedh.","also":["live","production"],"noTip":1},{"id":"change","g":"change","word":"Chanj","text":"Chanj towlennys dhe neppyth may trest an dus warnodho, skrifys kynsa: pyth, prag, an peryl, pan, ha fatell y dhiswul. Dalleth onan gans 🔀 Derevel chanj.","also":["chanjyow","govyn chanj","change request"],"noTip":1},{"id":"risk","g":"change","word":"Peryl","text":"Neppyth a yll mos kamm, skorys herwydh pes chons yw ha pes drog via. ⚠️ Peryllow a's gwith yn unn rol, an skor ughella kynsa, pub onan gans dydh dhe vires arta.","also":["peryllow","kovskrif peryllow"]},{"id":"chgwin","g":"change","word":"Fenester chanj","text":"An prysyow may hyll chanjyow mos yn fyw, kepar ha gorthugher kosel dy' Meurth. Mes a fenester ny yllir gorfenna kard chanj, marnas mars yw a-dhistowgh.","also":["fenestri chanj","change window"]},{"id":"gonogo","g":"change","word":"Ke / na ke","text":"Raglev skyff kyns ys dell dhe chanj yn fyw: pub den a res dhodho assentya a lever Ke po Na ke. Ny bes saw pan vons unnver.","also":["go/no go","go-no-go"]},{"id":"approval","g":"change","word":"Assentyans","text":"Gortos ya kyns ys dell dhallath an ober. Kard a dherev kothman, po chanj, a worta yn ✅ Assentyansow erna'n assentydh po erna'n nahydh.","also":["assentyansow","approval"]},{"id":"quiettime","g":"change","word":"Prys kosel","text":"Spys termyn, kepar ha stream, demo po an nos, ma na dhe travyth yn fyw. An bagasow a bes ow oberi hag ow previ, mes mos yn fyw a worta erna worfenno. Yn leow erell y'n gelwir change freeze.","also":["prysyow kosel","change freeze"]},{"id":"service","g":"run","word":"Gwassanaeth","text":"Neppyth a wrussys may trest an dus warnodho, kepar ha gwiasva po app, gwithys may pesso ow oberi. Merk “Gwassanaeth yw an towl ma” ha lavar pyth a brof, piw a'n us ha piw yw war alow.","also":["gwassanaethow","service"]},{"id":"uptime","g":"run","word":"Gwithrans uptime","text":"Gwithrans awtomatek, pub nebes mynysen, may fo dha wassanaeth ow korthebi hwath. Mar fyll ev lies treveth an eyl wosa y gila, AI-gile a ygor kard hwarvos drog y honan.","also":["uptime","gwithransow uptime"]},{"id":"statuspage","g":"run","word":"Folen studh","text":"Folen boblek a dhiskwedh mars yw gwassanaeth ow oberi (gwyrdh, rudhvelyn po rudh) gans an nowodhow diwettha, may hallo an dus a'n us mires ena yn le govyn.","also":["folennow studh","status page"]},{"id":"desk","g":"run","word":"Desk gwassanaeth","text":"An le may teu govynnow ha derivasow dhyworth an dus a us dha wassanaeth. AI-gile a dhidhol pubonan yn govyn, hwarvos drog po tybyans, hag a lever mar kwra hevelebi dhe neppyth derivys seulabrys.","also":["deskow gwassanaeth","desk gweres","helpdesk"]},{"id":"svcrequest","g":"run","word":"Govyn gwassanaeth","text":"Nebonan ow kovyn neppyth kemmyn, kepar ha akont nowydh po nebes gweres, yn le derivas bos neppyth terrys. Y'n gortos y dorn; hwarvos drog a dhe kynsa.","also":["govynnow gwassanaeth","govyn"]},{"id":"incident","g":"run","word":"Hwarvos drog","text":"Neppyth yw terrys rag an dus a'n us lemmyn, kepar ha'n wiasva dhe goedha. Kard 🔥 hwarvos drog a lamm dres an rew: y wul dhe oberi arta a dhe kynsa.","also":["hwarvosow drog","incident"]},{"id":"major","g":"run","word":"Hwarvos drog bras","text":"Hwarvos drog meur: lies den tochys, po arghans po data yn peryl. Unn boton a worr pub bagas warnodho (swarm), a dhifun neb yw war alow hag a wovyn nowodhow studh pub 30 mynysen.","also":["hwarvosow drog bras","major incident"]},{"id":"oncall","g":"run","word":"War alow","text":"Bos an den a worthyp pan dorr neppyth, kyn fo dres nos. Pub gwassanaeth a'n jeves esel bagas war alow neb a vydh difunys kynsa rag y hwarvosow drog.","also":["on call","on-call"]},{"id":"replyby","g":"run","word":"Termyn gorthyp","text":"Pes termyn a yll kard gortos rag an kynsa gorthyp, rag ensampel eur rag hwarvos drog. Wosa henna ev a gav klokk rudh, ma na vo travyth ankevys yn kosel. Henwys amkan gorthyp ynwedh.","also":["termynyow gorthyp","amkan gorthyp","response target"]},{"id":"postmortem","g":"run","word":"Post-mortem","text":"Golok verr war-dhelergh wosa hwarvos drog: pyth a hwarvas, pyth a weresas ha pyth dhe janjya, heb blamya den vyth. Ny yllir degea hwarvos drog hebdho.","also":["post-mortems","postmortem","daswel wosa hwarvos"]},{"id":"problem","g":"run","word":"Kudyn","text":"An acheson kudh a-dryv onan po moy a hwarvosow drog. Kard 🧩 kudyn a guntell hwarvosow drog a dhe arta hag arta, may fo an acheson kevys hag ewnhes bys vykken.","also":["kudyn","kudynnow","problem"],"noTip":1},{"id":"rootcause","g":"run","word":"Gwreydh an acheson","text":"An gwir reson may torras neppyth, na an pyth a welsys ow mos kamm hepken. Ewn gwreydh an acheson ha'n hwarvos drog a hedh dhe dhewhelel.","also":["root cause"]},{"id":"workaround","g":"run","word":"Fordh a-dro","text":"Fordh dhe synsi taklow ow oberi erna vo an gwir ewnans parys, kepar ha dalleth neppyth arta pan vo glenys. Skrifys yw war an kard kudyn ma na res dhe dhen vyth y gavos arta.","also":["fordhow a-dro","workaround"]},{"id":"knownerror","g":"run","word":"Gwall aswonnys","text":"Kudyn a'n jeves acheson konvedhys ha fordh a-dro, mes nag yw ewnhes hwath. 🧩 Gwallow aswonnys a's rester, may hwrello pubonan usya an fordh a-dro yn le palas arta.","also":["gwallow aswonnys","known error"]},{"id":"runbook","g":"run","word":"Runbook","text":"Kevarwodhyow kamm ha kamm rag ewna sort aswonnys a ankombrynsi, may fo gwrys an keth fordh, yn uskis, pub treveth. Wosa hwarvos drog bras an bagas a yll profya onan rag dha OK.","also":["runbook","runbooks"]},{"id":"ci","g":"run","word":"Taklenn kevreth","text":"Unn dra may hwra dha wassanaeth serri warnodho, kepar ha servyer, domayn, kartenn kummyas, alwhedh po provor. 🗂️ Taklow kevreth a's rol herwydh gwassanaeth, may hylli gweles pyth a dheg hwarvos drog ha pyth a res bos nowydhhes po kopiys.","also":["taklow kevreth","taklenn gevreth"]},{"id":"expiry","g":"run","word":"Dedh diwedh","text":"AI-gile a with dedhyow kepar ha pan dhe kartenn kummyas po domayn dhe benn. Deg dydh warn ugens kyns an dedh y hwra unn kard rag y nowydhhe, ytho ny hedh travyth a-dhesempis.","also":["dedhyow diwedh","diwedh","goel diwedh"]},{"id":"backup","g":"run","word":"Kopi gwith","text":"Kopi gwithys a'th data a-gyns, dhe dhewhelel dhodho mar pydh neppyth kellys po shyndys. AI-gile a wra kopi gwith a'th vordys pub dydh.","also":["kopiow gwith","kopia","backup"]},{"id":"restore","g":"run","word":"Daskorra","text":"Gorra data war-dhelergh a gopi gwith. Ny dal kopi gwith yn hwir erna wodhes y hyllir y dhaskorra, ytho talvos yw y assaya a-dhiworth prys dhe brys.","also":["daskorrys","restore"]},{"id":"svcreview","g":"run","word":"Daswel gwassanaeth","text":"Golok war-dhelergh war unn mis a wassanaeth: hwarvosow drog ygerys hag ewnys, pyth uskis a gavas an dus gorthyp, uptime ha tokens usys. An Daswel misyek a'n diskwa rag pub gwassanaeth.","also":["daswelyow gwassanaeth","daswel misyek","daswelyow misyek"]},{"id":"accessreview","g":"run","word":"Daswel entrans","text":"Gwiryas pub 90 dydh piw a yll entra hwath: kevrennow kevrenna, rolyow kothmans ha sekretys gwithys. Ty a with po a dhilea pubonan, ytho ny dregh entrans koth.","also":["daswelyow entrans","daswel an entrans"]},{"id":"improvements","g":"run","word":"Rol gwellheansow","text":"Pub tra may tybis an bagas gul gwell, yn unn le: profyansow retro, gwriansow daswel hag ewnansow kudynnow, pubonan gans y studh. Kav e yn-dann 📈 Gwellheansow.","also":["rolyow gwellheansow","gwellheansow"]},{"id":"tokencap","g":"run","word":"Finweth tokens","text":"Finweth misyek war an tokens a yll ajentow gwassanaeth usya. Orth 80% ty a gyv gwarnyans; orth 100% aga ober a-dryv a worta bys y'n nessa mis po bys pan dhrehevydh an finweth.","also":["finwethow tokens","finweth tokens misyek"]},{"id":"backlog","g":"team","word":"Backlog","text":"Tybyansow hag ober nag yw towlennys hwath. Ny vydh travyth ena gwrys erna vo movys dhe Dhe wul."},{"id":"sprint","g":"team","word":"Sprint","text":"Termyn berr a oberow (menowgh unn seythun po dew) gans set ervys a gardys dhe worfenna.","also":["sprints"]},{"id":"standup","g":"team","word":"Kuntelles sav","text":"Gwithrans skyff: pyth a wrug pub esel a'n bagas, pyth a wra nessa, ha pyth a'n lett.","also":["standup","stand-ups"]},{"id":"kanban","g":"team","word":"Kanban","text":"Bord gans kolonnow (Dhe wul, Yn hwel, Gwrys) may movyons kardys a-gledh dhe'n dyhow hag an ober ow hwarvos."},{"id":"wip","g":"team","word":"Finweth WIP","text":"Ober yn hwel: an niver moyha a gardys y tal dhe golonn synsi, may hworffenno an bagas taklow kyns dalleth moy.","also":["WIP"]},{"id":"dod","g":"team","word":"Definition of Done","text":"Rol gwithra verr an bagas a'n pyth a styr “gorfennys”, kepar ha previs ha displegys, kyns ys dell vydh kard rys dhis. Y gevell, an Definition of Ready, a lever pan yw kard kler lowr dhe dhalleth.","also":["Definition of Ready"]},{"id":"testpile","g":"team","word":"Graghell previ","text":"An kardys gorfennys ow kortos ty dhe'ga assaya, onan wosa y gila. Assent onan po danvon e war-dhelergh gans noten, ha'n nessa a dhe.","also":["graghellow previ","test pile"]},{"id":"retro","g":"team","word":"Retro","text":"Golok war-dhelergh orth fatell ober an bagas, rag bos unnver war unn dra dhe wul gwell. Yn AI-gile retro a brof chanj dhe fordhow oberi an bagas, ha ty a lever Ke po Na hwath.","also":["retros","retrospective","daswel"]},{"id":"peerreview","g":"team","word":"Daswel gans par","text":"Dewlagas moy: AI aral a withra ober pub kard kyns ys dell dhe dhis, ma na dremenno mar lies kammwrians.","also":["peer review","code review"]},{"id":"swarm","g":"team","word":"Swarm","text":"Pub dorn dhe'n ober: pub bagas a as ober aral rag gweres unn towl a-dhistowgh erna vo kempennys. Towlow erell a worta y'n kettermyn.","also":["swarm","swarming"]},{"id":"scrummaster","g":"team","word":"Scrum Master","text":"Neb a syns an ober ow resek: ev a verk kardys glenys, a bok an bagasow hag a'th kovha a'n pyth ow kortos. Yn AI-gile an Penn Scrum Master a wra henna dres pub towl.","also":["Penn Scrum Master","Lead Scrum Master"]},{"id":"agent","g":"team","word":"Ajent","text":"AI a ober y honan war dasek: a red an kod, a wra chanjyow, a ren gwithransow, hag a dheriv.","also":["agents"]},{"id":"token","g":"team","word":"Token","text":"An unita may fydh devnydh AI nivrys: ogas dhe nebes lytherennow a dekst redys po skrifys. Le a tokens, moy a'th kevambos gesys.","also":["tokens"]},{"id":"hook","g":"team","word":"Hook","text":"Gorhemmyn byghan a ren y honan orth prys ervys, y.h. pan dhallath sesyon AI, may klywo an bagas dha notyansow.","also":["hooks"]}]}};
